      data_list = trim_proc(data_list);
      is_DAILY_MT_length = data_list.length;

      setState(() {

      });

    }
    catch(e){
      dev.log("${e}");
      //EasyLoading.showInfo("錯誤:${e}");
    }
  }

  /*
  [托嬰/幼兒]  家長回簽
   */
  Future<void>DAILY_PRS_db_sub()async{

    List<String> CS_NOs = [];
    for(int i=0;i<cUSTOMERs.length;i++){
      CS_NOs.add(cUSTOMERs[i].CS_NO);
    }
    String CS_NO_json = jsonEncode(CS_NOs.toList());
    CS_NO_json = CS_NO_json.replaceAll("[", "(");
    CS_NO_json = CS_NO_json.replaceAll("]", ")");
    CS_NO_json = CS_NO_json.replaceAll("\"", "'");

    String datetime = "${DateFormat('yyyy-MM-dd').format(DateTime.now()!)}";
    String comm = "SELECT * FROM DAILY_PRS WHERE (CS_NO in ${CS_NO_json}) AND (DATE BETWEEN '${datetime} 00:00:00' AND '${datetime} 23:59:59')";
    String result = await sql_command("${comm}");
    try{
      List<dynamic> list = jsonDecode(result);
      List<dynamic> data_list = [];
      if(Platform.isAndroid){
        data_list = list;
      }
      else if(Platform.isIOS){
        data_list = list;
      }
      data_list = trim_proc(data_list);
      if(data_list.length!=cUSTOMERs.length){
        dev.log("家長尚未回簽");

        show_DAILY_PRS_SIGN_LINK_name.clear();
        for(int i=0;i<cUSTOMERs.length;i++){
          cUSTOMERs[i].is_DAILY_PRS = false;
        }

        for(int i=0;i<cUSTOMERs.length;i++){
          for(int j=0;j<data_list.length;j++){
             if(cUSTOMERs[i].CS_NO==data_list[j]["CS_NO"]){
               cUSTOMERs[i].is_DAILY_PRS = true;
             }
          }
        }

        for(int i=0;i<cUSTOMERs.length;i++){
          if(cUSTOMERs[i].is_DAILY_PRS == false){
            show_DAILY_PRS_SIGN_LINK_name.add(cUSTOMERs[i].CS_NM);
          }
        }
        is_DAILY_PRS_SIGN_LINK_flag = false;
      }
      else{
        is_DAILY_PRS_SIGN_LINK_flag = true;
      }

      setState(() {

      });

    }
    catch(e){
      dev.log("${e}");
      //EasyLoading.showInfo("錯誤:${e}");
    }
  }


