  /*
  公告欄 INTRODUCTION
   */
  Future<void> BULLETIN_db_sub({String datetime="",String SORT_ID="",bool is_show_dialog = true})async{
    FocusManager.instance.primaryFocus?.unfocus();
    if(is_show_dialog){
      SmartDialog.showLoading(msg: "處理中...");
      await Future.delayed(const Duration(milliseconds: 500), () {});
    }
    BULLETIN_list.clear();
    setState(() {

    });
    /*
    String result = await sql_command("SELECT * FROM BULLETIN WHERE BLTN_DT BETWEEN '${datetime} 00:00:00' AND '${datetime} 23:59:59'");

     */
    String target_DEPM_NO = cUSTOMERs
        .where((c) => c.checkbox)
        .map((c) => "'${c.DEPM_NO}'")
        .join(',');

    String comm = (SORT_ID.isEmpty)?
    '''
    SELECT *
FROM BULLETIN
WHERE DEPM_NO IN (${target_DEPM_NO})
  AND BLTN_DT >= DATEADD(MONTH, -6, GETDATE());
    '''
        :
    '''
    SELECT * FROM BULLETIN WHERE DEPM_NO IN (${target_DEPM_NO}) AND SORT_ID IN(${SORT_ID}) AND BLTN_DT >= DATEADD(MONTH, -6, GETDATE());
    ''';
    dev.log(comm);
    String result = await sql_command(comm);
    List<BULLETIN> _BULLETIN_list = [];
    SmartDialog.dismiss();
    try{
      List<dynamic> list = jsonDecode(result);
      List<dynamic> data_list = [];
      if(Platform.isAndroid){
        data_list = list;
      }
      else if(Platform.isIOS){
        data_list = list;
      }
      data_list = trim_proc(data_list);
      if(data_list.length==0){
      }
      else{
         for(int i=0;i<data_list.length;i++){
           BULLETIN b = BULLETIN();
           b.BLTN_NO = "${data_list[i]["BLTN_NO"]}".contains("null")?"":"${data_list[i]["BLTN_NO"]}";
           b.TITLE = "${data_list[i]["TITLE"]}".contains("null")?"":"${data_list[i]["TITLE"]}";
           b.DETAIL = "${data_list[i]["DETAIL"]}".contains("null")?"":"${data_list[i]["DETAIL"]}";
           b.BLTN_DT = "${data_list[i]["BLTN_DT"]}".contains("null")?"":"${data_list[i]["BLTN_DT"]}";
           b.SORT_ID = "${data_list[i]["SORT_ID"]}".contains("null")?"":"${data_list[i]["SORT_ID"]}";
           b.DEPM_NO = "${data_list[i]["DEPM_NO"]}".contains("null")?"":"${data_list[i]["DEPM_NO"]}";
           b.NOTE = "${data_list[i]["NOTE"]}".contains("null")?"":"${data_list[i]["NOTE"]}";
           DateTime d = DateTime.parse(b.BLTN_DT);
           b.BLTN_DT = DateFormat("yyyy年MM月dd日").format(d);
           _BULLETIN_list.add(b);
         }
      }
      BULLETIN_list = _BULLETIN_list;
      BULLETIN_list.sort((a,b) => b.BLTN_DT.compareTo(a.BLTN_DT));
      setState(() {

      });

      final stopwatch = Stopwatch()..start();

      /*
      公告欄子表單 BULLETIN_DL
       */
      /*
      dev.log("BULLETIN_list.length:${BULLETIN_list.length}");
      for(int i=0;i<BULLETIN_list.length;i++){
        await BULLETIN_DL_db_sub(BLTN_NO:BULLETIN_list[i].BLTN_NO,index:i);
      }

       */

      //dev.log('執行時間: ${stopwatch.elapsedMilliseconds} 毫秒');


      // 假設你已有 BULLETIN_list，且每個元素都有 BLTN_NO 屬性
      List<String> bltnNos = BULLETIN_list
          .map((item) => item.BLTN_NO.toString())
          .where((no) => no.isNotEmpty)
          .toList();

      // 防呆：如果陣列是空的就不查
      if (bltnNos.isEmpty) {
        dev.log("沒有可查詢的 BLTN_NO");
        setState(() {

        });
        return;
      }



      // 組成 IN 子句
      String inClause = bltnNos.map((e) => "'$e'").join(",");
      // 組出 SQL 字串
      String sql = "SELECT * FROM BULLETIN_DL WHERE BLTN_NO IN ($inClause)";
      // 執行查詢
      result = await sql_command(sql);

      List<dynamic> data_list2 = jsonDecode(result);

      for(int i=0;i<data_list2.length;i++){
        BULLETIN_DL b = BULLETIN_DL();
        b.BLTN_NO = "${data_list2[i]["BLTN_NO"]}".contains("null")?"":"${data_list2[i]["BLTN_NO"]}";
        b.BLTN_SR = "${data_list2[i]["BLTN_SR"]}".contains("null")?"":"${data_list2[i]["BLTN_SR"]}";
        b.LINK = "${data_list2[i]["LINK"]}".contains("null")?"":"${data_list2[i]["LINK"]}";
        b.NOTE = "${data_list2[i]["NOTE"]}".contains("null")?"":"${data_list2[i]["NOTE"]}";
        String LINK = b.LINK.replaceAll("~/", "");
        b.LINK = "${IMAGE_IP}/${LINK}";
        // 找出與 BLTN_NO 相同的 bulletin
        for (int j = 0; j < BULLETIN_list.length; j++) {
          if (BULLETIN_list[j].BLTN_NO == b.BLTN_NO) {
            BULLETIN_list[j].BULLETIN_DL_list.add(b);
            break; // 找到就結束內層迴圈
          }
        }
      }

      stopwatch.stop();

      dev.log('執行時間: ${stopwatch.elapsedMilliseconds} 毫秒');



    }
    catch(e){
      dev.log("${e}");
      SmartDialog.showToast("網路異常");
    }
  }


