            DateTime dateTime = DateTime.parse(b.CFM_DT);
            b.CFM_DT_str = "${DateFormat("yyyy年MM月dd日 HH:mm:ss").format(dateTime)} (${WEEK_DAY[dateTime.weekday-1]})";
          }
