  Future<void> read_for_View_LOGIN_db_sub()async{
    //await EasyLoading.show(status: "處理中...");
    cUSTOMERs.clear();
    setState(() {

    });
    String result = await sql_command("SELECT * FROM [View_LOGIN] WHERE ACCOUNT = '${user.ACCOUNT}'");
    SmartDialog.dismiss();
    try{
      List<dynamic> list = jsonDecode(result);
      dev.log("list.length:${list[0]}");
      List<dynamic> data_list = [];
      if(Platform.isAndroid){
        data_list = list;
      }
      else if(Platform.isIOS){
        data_list = list;
      }
      data_list = trim_proc(data_list);
      if(data_list.length==0){
        //EasyLoading.showInfo("請確認帳號密碼是否正確");
      }
      else{

        for(int i=0;i<data_list.length;i++){
           await read_for_CUSTOMER_db_sub(CS_NO:"${data_list[i]["KIDS_NO"]}");
        }

        for(int i=0;i<cUSTOMERs.length;i++){
          await read_for_CUSTOMER_DL_db_sub(CS_NO:"${cUSTOMERs[i].CS_NO}",index: i);
        }

        dev.log("cUSTOMERs.length:${cUSTOMERs.length}");
        for(int i=0;i<cUSTOMERs.length;i++){
          cUSTOMERs[i].cLASS_NO_for_teacher.clear();
          for(int j=0;j<eMPLOYEEs.length;j++){
            if(cUSTOMERs[i].CLASS_NO==eMPLOYEEs[j].CLASS_NO){
              cUSTOMERs[i].cLASS_NO_for_teacher.add(eMPLOYEEs[j]);
            }
          }
        }


        /*
        找出有幾個老師聊天室
         */
        cLASS_NO_for_teacher_chat.clear();
        bool check = false;
        for(int i=0;i<cUSTOMERs.length;i++){
          for(int j=0;j<cUSTOMERs[i].cLASS_NO_for_teacher.length;j++){
            check = false;
            for(int k=0;k<cLASS_NO_for_teacher_chat.length;k++){
              if(cUSTOMERs[i].cLASS_NO_for_teacher[j].EMP_NO==cLASS_NO_for_teacher_chat[k].EMP_NO){
                check = true;
                break;
              }
            }
            if(check==false){
              cLASS_NO_for_teacher_chat.add(cUSTOMERs[i].cLASS_NO_for_teacher[j]);
            }
          }
        }
        dev.log("cLASS_NO_for_teacher_chat.length:${cLASS_NO_for_teacher_chat.length}");



      }

    }
    catch(e){
      dev.log("${e}");
      SmartDialog.showToast("網路異常");
    }
  }



