            }
          }
        }


      }

    }
    catch(e){
      dev.log("${e}");
    }

  }



  /*
  檢查聊天室未讀數量
   */
  void check_unread_chat_sub()async{
    //await EasyLoading.show(status: "處理中...");

    for(int i=0;i<cUSTOMERs.length;i++){
      if(cUSTOMERs[i].ChatID.isEmpty){
        await check_is_ChatID_sub(
          //UserAccount: '${cUSTOMERs[i].cUSTOMER_DL!.ACCOUNT.trim()}',
          //TeacherAccount:"${cLASS_NO_for_teacher_chat[i].ACCOUNT}",
          CS_NO:cUSTOMERs[i].CS_NO,
          CLASS_NO:cUSTOMERs[i].CLASS_NO,
          DEPM_NO:cUSTOMERs[i].DEPM_NO,
          index:i,
        );//檢查是否已建立聊天室
      }
    }

    //讀取最後一筆訊息

    // 1. 收集所有 ChatID
    List<String> chatIds = cUSTOMERs
        .map((c) => "'${c.ChatID}'") // 注意加上引號
        .toList();

    // 2. 組合成 IN 的 SQL 字串
    String chatIdList = chatIds.join(",");

    // 3. 建立 SQL 查詢一次撈取
    String comm = """
SELECT ChatID, UnreadCount 
FROM View_Chatid_UnreaderCount 
WHERE ChatID IN (${chatIdList}) 
AND USER_NO='${user.ACCOUNT}'
""";

    String result = await sql_command(comm);

    // 4. 將查詢結果轉成 Map<ChatID, UnreadCount>
    // 將查詢結果轉成 Map<int, int>
    Map<int, int> unreadMap = {};
    try {
      List<dynamic> maps = jsonDecode(result);
      for (var row in maps) {
        int? chatId = int.tryParse("${row["ChatID"]}");
        if (chatId != null) {
          unreadMap[chatId] = int.tryParse("${row["UnreadCount"]}") ?? 0;
        }
      }
    } catch (e) {
      unreadMap = {};
    }

    //dev.log("unreadMap:${unreadMap}");
    // 5. 將對應值回填進每個 CUSTOMER 物件
    for (int i = 0; i < cUSTOMERs.length; i++) {
      var customer = cUSTOMERs[i];
      int? chatId = int.tryParse("${customer.ChatID}");
      //dev.log("unreadMap[$chatId]: ${unreadMap[chatId]}");
      cUSTOMERs[i].unread_count = unreadMap[chatId] ?? 0;
    }

    comm = """
SELECT *
FROM (
    SELECT *, ROW_NUMBER() OVER (PARTITION BY ChatID ORDER BY CreatedAt DESC) AS rn
    FROM MSDL2
    WHERE ChatID IN (${chatIdList})
) t
WHERE rn = 1
""";
    try{
      result = await sql_command(comm);
      List<dynamic> maps = jsonDecode(result);
      maps = trim_proc(maps);
      for(int i=0;i<maps.length;i++){
        for(int j=0;j<cUSTOMERs.length;j++){
          //dev.log(">>>,${EMPLOYEE_teacher.Teacher_CUSTOMER_selectedValue.cUSTOMERs[j].ChatID},${maps[i]["ChatID"]}");
          if(cUSTOMERs[j].ChatID==maps[i]["ChatID"]){
            //dev.log("Type:${maps[i]["Type"]}");
            //先檢查留言者是家長還是老師
            bool is_teacher = true;
            for(int k=0;k<cUSTOMERs.length;k++){
              for(int m=0;m<cUSTOMERs[k].cUSTOMER_DLs.length;m++){
                if(cUSTOMERs[k].cUSTOMER_DLs[m]!.ACCOUNT=="${maps[i]["AuthorID"]}"){
                  is_teacher = false;
                  break;
                }
              }
            }
            if(is_teacher==true){
              if("${maps[i]["Type"]}"=="text"){
                cUSTOMERs[j].last_message = "老師 ${maps[i]["Text"]}";
              }
              else{
                cUSTOMERs[j].last_message = "老師 傳送一張圖片";
              }
            }
            else{
              if("${maps[i]["Type"]}"=="text"){
                cUSTOMERs[j].last_message = "${maps[i]["AuthorFirstName"]} ${maps[i]["Text"]}";
              }
              else{
                cUSTOMERs[j].last_message = "${maps[i]["AuthorFirstName"]} 傳送一張圖片";
              }
            }

          }
        }
      }
    }
    catch(e){

    }


    /*
    for(int i=0;i<cUSTOMERs.length;i++){
      await check_is_ChatID_sub(
        //UserAccount: '${cUSTOMERs[i].cUSTOMER_DL!.ACCOUNT.trim()}',
        //TeacherAccount:"${cLASS_NO_for_teacher_chat[i].ACCOUNT}",
        CS_NO:cUSTOMERs[i].CS_NO,
        CLASS_NO:cUSTOMERs[i].CLASS_NO,
        DEPM_NO:cUSTOMERs[i].DEPM_NO,
        index:i,
      );//檢查是否已建立聊天室


    }

     */
    //await EasyLoading.dismiss();
  }

  /*
  檢查是否已建立聊天室
   */
  Future<void>check_is_ChatID_sub(
      {
        String TeacherAccount="",
        String UserAccount="",
        String CS_NO="",
        String CLASS_NO="",
        String DEPM_NO="",
        int index=0,
      })async{

    String ChatID = "";

    TeacherAccount = TeacherAccount.trim();
    UserAccount = UserAccount.trim();
    CS_NO = CS_NO.trim();

    String result = await sql_command("SELECT * FROM MSMT2 WHERE CS_NO='${CS_NO}' AND CLASS_NO='${CLASS_NO}' AND DEPM_NO='${DEPM_NO}'");
    //await EasyLoading.dismiss();
    try{
      List<dynamic> list = jsonDecode(result);
      List<dynamic> data_list = [];
      if(Platform.isAndroid){
        data_list = list;
      }
      else if(Platform.isIOS){
        data_list = list;
      }

      dev.log("data_list.length:${data_list.length}");
      if(data_list.length==0){
        dev.log("尚未建立聊天室");
        cUSTOMERs[index].unread_count = 0;
      }
      else{
        dev.log("已建立聊天室");
        //ChatID = await get_ChatID_form_MSMT2_db_sub(CS_NO:CS_NO,CLASS_NO:CLASS_NO,DEPM_NO:DEPM_NO);
        ChatID = data_list[0]["ChatID"].toString().trim();
        dev.log("ChatID:${ChatID}");
        cUSTOMERs[index].ChatID=ChatID;
        if(cUSTOMERs[index].ChatID.isNotEmpty){
          //await _loadMessages(index:index,ChatID:ChatID);
        }
      }

    }
    catch(e){
      dev.log("${e}");
      //EasyLoading.showInfo("錯誤:${e}");
    }
  }


