  Future<void> _loadMessages(
      {
        String ChatID = "",
        String TeacherAccount="",
        int index=0,
      }) async {

    DateTime datetime = DateTime.now();
    //String comm = "SELECT * FROM MSDL2 WHERE (ChatID='${ChatID}') AND (CreatedAt BETWEEN '${DateFormat("yyyy-MM-dd").format(datetime.subtract(Duration(days: 30)))} 00:00:00' AND '${DateFormat("yyyy-MM-dd").format(datetime)} 23:59:59')";
    String comm = '''SELECT TOP 15 *
FROM MSDL2
WHERE ChatID = '${ChatID}'
 ORDER BY CreatedAt DESC''';
    dev.log("${comm}");
    String result = await sql_command("${comm}");
    //await EasyLoading.dismiss();
    try{

      List<dynamic> list = jsonDecode(result);
      List<dynamic> data_list = [];
      if(Platform.isAndroid){
        data_list = list;
      }
      else if(Platform.isIOS){
        data_list = list;
      }
      dev.log("data_list.length:${data_list.length}");


      //dev.log("Type>>${data_list[0]["Type"]}");
      if("${data_list[0]["Type"]}".contains("image")){
        cUSTOMERs[index].last_message = "傳送一張圖片";
      }
      else{
