BEGIN TRANSACTION;

-- 1. 鎖住以避免同時搶 SR 序號
DECLARE @MAX_SR INT;
SELECT @MAX_SR = MAX(CAST(SR AS INT))
FROM SURVEY_RT WITH (UPDLOCK, HOLDLOCK)
WHERE NO = '${SURVEY_list[index].NO}';

IF @MAX_SR IS NULL
    SET @MAX_SR = 1;
ELSE
    SET @MAX_SR = @MAX_SR + 1;

-- 2. 確認是否存在該筆資料
IF EXISTS (
    SELECT 1
    FROM SURVEY_RT
    WHERE NO = '${SURVEY_list[index].NO}' AND ACCOUNT = '${user.ACCOUNT}' AND CS_NO = '${CUSTOMER_selectedValue.CS_NO}' AND CLASS_NO = '${CUSTOMER_selectedValue.CLASS_NO}'
)
BEGIN
    -- 4. 資料存在 → UPDATE
    UPDATE SURVEY_RT
    SET
        ANSWER = '${ANSWER}',
        DATETIME = '${DATETIME}',
        NOTE = '${SURVEY_list[index].NOTE_textEditingController.text}'
    WHERE NO = '${SURVEY_list[index].NO}' AND ACCOUNT = '${user.ACCOUNT}' AND CS_NO = '${CUSTOMER_selectedValue.CS_NO}' AND CLASS_NO = '${CUSTOMER_selectedValue.CLASS_NO}';
END
ELSE
BEGIN
    -- 3. 新資料 → INSERT，SR = @MAX_SR
    DECLARE @NEW_SR CHAR(4);
    SET @NEW_SR = CAST(@MAX_SR AS VARCHAR);  -- 不補0，直接轉字串

    -- 5. 執行 INSERT
    INSERT INTO SURVEY_RT (NO, SR, ANSWER, ACCOUNT, DATETIME, NOTE, CLASS_NO, CS_NO)
