                        v.DateStr = "${list[0]}年${list[1]}月${list[2]}日 (${WEEK_DAY[DateTime(int.parse(list[0]),int.parse(list[1]),int.parse(list[2])).weekday-1]})";
                        _view_DAILY_ROLLCALL_RUG_MTs.add(v);
                      }
                    }

                    //將同日期放在一起
                    for(int i=0;i<_view_DAILY_ROLLCALL_RUG_MTs.length;i++){
                      for(int j=0;j<view_DAILYs.length;j++){
                        if(DateFormat("yyyy-MM-dd").format(DateTime.parse(view_DAILYs[j].DATE))==_view_DAILY_ROLLCALL_RUG_MTs[i].DATE &&
                            view_DAILYs[j].CS_NO==_view_DAILY_ROLLCALL_RUG_MTs[i].CS_NO
