                          _view_DAILY_ROLLCALL_RUG_MTs[i].view_DAILYs.add(view_DAILYs[j]);
                        }
                      }
                    }
                    for(int i=0;i<_view_DAILY_ROLLCALL_RUG_MTs.length;i++){
                      for(int j=0;j<ROLLCALL_list.length;j++){
                        if(DateFormat("yyyy-MM-dd").format(DateTime.parse(ROLLCALL_list[j].DATE))==_view_DAILY_ROLLCALL_RUG_MTs[i].DATE &&
