                      for(int j=0;j<DAILY_PRSs.length;j++){
                        if(DateFormat("yyyy-MM-dd").format(DateTime.parse(DAILY_PRSs[j].DATE))==_view_DAILY_ROLLCALL_RUG_MTs[i].DATE &&
                            DAILY_PRSs[j].CS_NO==_view_DAILY_ROLLCALL_RUG_MTs[i].CS_NO
                        ){
                          _view_DAILY_ROLLCALL_RUG_MTs[i].DAILY_PRSs.add(DAILY_PRSs[j]);
                        }
                      }
                    }

                    view_DAILY_ROLLCALL_RUG_MTs = _view_DAILY_ROLLCALL_RUG_MTs;
                    view_DAILY_ROLLCALL_RUG_MTs.sort((a,b)=>b.DATE.compareTo(a.DATE));

                    SmartDialog.dismiss();
